query:
query postureDefinitionList ( $accountId:ID! $postureDefinitionListInput:PostureDefinitionListInput) {
	posture ( accountId:$accountId ) {
		definitionList ( input:$postureDefinitionListInput  )  {
			items {
				id
				name
				description
				tags
				impact
				recommendedActions {
					recommendedAction
					recommendedActionLink {
						text
						url
					}
				}
				suppressedStatus
				category {
					id
					name
				}
				domain {
					id
					name
				}
				area {
					id
					name
				}
				complianceFrameworks
				complianceControls {
					framework
					key
					title
					description
				}
				application
				checkType
				securityDomain
			}
			paging {
				total
			}
		}
	}	
}
